declarations.BHF:
public class BHF {
 public Datetime dt(String value) { return Datetime.valueOfGmt(value); }
 public String stamp(Datetime value) { return value == null ? 'null' : value.formatGmt('yyyy-MM-dd HH:mm:ss.SSS'); }
}

